GillMixEditor::GillMixEditor(GillMixProcessor&p):AudioProcessorEditor(p),processor(p),quality(p.apvts,p){
 look=std::make_unique<MixLook>();setLookAndFeel(look.get());wood=juce::ImageCache::getFromMemory(BinaryData::core_reference_png,BinaryData::core_reference_pngSize);
 setSize(780,p.kind==GillMixKind::master?540:450);setResizable(false,false);
 addAndMakeVisible(quality);addAndMakeVisible(status);addAndMakeVisible(inMeter);addAndMakeVisible(outMeter);
 for(auto*l:{&status,&inMeter,&outMeter,&title,&limitTitle})l->setColour(juce::Label::textColourId,gill::twin::ink);
 status.setColour(juce::Label::textColourId,gill::prism::ink);status.setFont(juce::FontOptions(12));status.setJustificationType(juce::Justification::centredLeft);
 if(p.kind==GillMixKind::master){
  addAndMakeVisible(name);name.setText(juce::String::fromUTF8(p.localSnapshot().name));name.setTooltip("Session name. Connections are explicit and scoped to this controller.");name.onReturnKey=[this]{processor.setLocalName(name.getText());name.giveAwayKeyboardFocus();};name.onFocusLost=[this]{processor.setLocalName(name.getText());};
  addAndMakeVisible(identity);identity.setButtonText("NEW SESSION");identity.setTooltip("Create a new session identity and remove this controller's previous remote authority. Local LINK levels stay unchanged.");identity.onClick=[this]{processor.newIdentity();processor.service();};
  for(auto*b:{&connect,&learn,&apply,&undo}){addAndMakeVisible(b);b->setColour(juce::TextButton::buttonColourId,juce::Colour(0xffd4bea0));b->setColour(juce::TextButton::textColourOffId,juce::Colour(0xff281b11));}
  learn.setTitle("LEARN / STOP");learn.setTooltip("Arm, play the whole song up to five minutes, then STOP to review. Transport stop or a seek also ends the current pass. Gains stay unchanged until APPLY.");connect.onClick=[this]{processor.connectSelected();};learn.onClick=[this]{if(processor.isLearning())processor.stopLearn();else processor.startLearn();};apply.onClick=[this]{processor.apply();};undo.onClick=[this]{processor.undo();};
  addAndMakeVisible(list);list.setRowHeight(33);list.setColour(juce::ListBox::backgroundColourId,juce::Colour(0xff101116));list.setTooltip("Keep selected FL track faders at 0 dB. Put LINK last on each source; adjust levels in LINK. Tick a link, CONNECT SELECTED, then click its row for role, lock or level. Do not also link a bus carrying the same source.");
  addAndMakeVisible(preset);for(int i=0;i<5;++i)preset.addItem(p.getProgramName(i),i+1);preset.setSelectedId(p.getCurrentProgram()+1,juce::dontSendNotification);preset.onChange=[this]{processor.setCurrentProgram(preset.getSelectedId()-1);};
  addAndMakeVisible(limit);limit.setSliderStyle(juce::Slider::LinearHorizontal);limit.setTextBoxStyle(juce::Slider::TextBoxRight,false,60,22);limit.setTextValueSuffix(" dB");limitAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,"changeLimit",limit);addAndMakeVisible(limitTitle);limitTitle.setText("CHANGE LIMIT",juce::dontSendNotification);
  const char* ids[]{"doubleOffset","adlibOffset","beatOffset"};const char* labels[]{"DOUBLE","ADLIB","BEAT"};
  for(size_t i=0;i<3;++i){addAndMakeVisible(offsets[i]);addAndMakeVisible(offsetLabels[i]);offsets[i].setSliderStyle(juce::Slider::LinearHorizontal);offsets[i].setTextBoxStyle(juce::Slider::TextBoxRight,false,58,21);offsets[i].setTextValueSuffix(" dB");offsetLabels[i].setText(labels[i],juce::dontSendNotification);offsetLabels[i].setFont(juce::FontOptions(11));offsetLabels[i].setColour(juce::Label::textColourId,gill::twin::ink);offsetAttachments[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,ids[i],offsets[i]);}

 }else{
  addAndMakeVisible(name);name.setText(juce::String::fromUTF8(p.localSnapshot().name));name.onReturnKey=[this]{processor.setLocalName(name.getText());name.giveAwayKeyboardFocus();};name.onFocusLost=[this]{processor.setLocalName(name.getText());};name.setTooltip("Track name is a hint, never a session identity.");
  addAndMakeVisible(role);for(int i=0;i<=4;++i)role.addItem(roleName(static_cast<Role>(i)),i+1);role.onChange=[this]{if(!updating)processor.setLocalRole(static_cast<Role>(role.getSelectedId()-1));};
  addAndMakeVisible(lock);lock.onClick=[this]{if(!updating)processor.setLocalLock(lock.getToggleState());};lock.setColour(juce::ToggleButton::textColourId,gill::prism::ink);lock.setColour(juce::ToggleButton::tickColourId,gill::prism::ink);lock.setColour(juce::ToggleButton::tickDisabledColourId,gill::prism::ink.withAlpha(.35f));inMeter.setColour(juce::Label::textColourId,gill::prism::ink);outMeter.setColour(juce::Label::textColourId,gill::prism::ink);
  addAndMakeVisible(gain);gain.setSliderStyle(juce::Slider::LinearVertical);gain.setTextBoxStyle(juce::Slider::TextBoxBelow,false,86,24);gainAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.apvts,"trackLevel",gain);
  addAndMakeVisible(identity);addAndMakeVisible(disconnect);identity.onClick=[this]{processor.newIdentity();};disconnect.onClick=[this]{processor.disconnect();};identity.setTooltip("Give this explicitly selected copy a new persistent ID. Existing binding is removed.");
 }
 timerCallback();startTimer(100);
}
GillMixEditor::~GillMixEditor(){stopTimer();list.setModel(nullptr);setLookAndFeel(nullptr);}
void GillMixEditor::paint(juce::Graphics&g){gill::twin::chassis(g,780,float(getHeight()),processor.getName());const bool master=processor.kind==GillMixKind::master;const float size=master?210.f:270.f,x=master?36.f:22.f,y=master?65.f:72.f;auto draw=[&](float xx,float gain,const char*caption){auto a=gill::twin::lens(g,{xx,y,size,size},caption,"CURRENT PEAK / DBFS");const float db=juce::Decibels::gainToDecibels(gain,-120.f);g.setColour(gill::twin::purple);g.fillRoundedRectangle(a.getX(),a.getCentreY(),juce::jlimit(0.f,1.f,(db+120)/120)*a.getWidth(),5,2);g.setColour(juce::Colours::white);g.setFont(juce::FontOptions(19));g.drawText(juce::String(db,1)+" dB",a.withY(a.getY()+8).withHeight(24),juce::Justification::centred);};draw(x,processor.meterIn(),"BEFORE");draw(780-x-size,processor.meterOut(),"AFTER");if(master){g.setFont(juce::FontOptions(10));g.setColour(gill::twin::ink);g.drawText("SELECT / TRACK",22,278,230,18,juce::Justification::centredLeft);g.drawText("ROLE",274,278,110,18,juce::Justification::centredLeft);g.drawText("LEVEL",413,278,85,18,juce::Justification::centredLeft);g.drawText("PROPOSAL",515,278,210,18,juce::Justification::centredLeft);g.drawText("TRACK FADERS 0 dB / LEVELS VIA GILLLINK",22,516,500,16,juce::Justification::centredLeft);}else{g.setColour(gill::twin::ink);g.setFont(juce::FontOptions(12));g.drawText("TRACK LEVEL",330,133,120,21,juce::Justification::centred);}}
void GillMixEditor::resized(){quality.setBounds(648,20,110,26);if(processor.kind==GillMixKind::master){name.setBounds(274,19,220,26);identity.setBounds(503,19,133,26);preset.setBounds(260,70,260,28);learn.setBounds(346,108,88,35);apply.setBounds(291,151,88,26);undo.setBounds(402,151,88,26);limitTitle.setBounds(270,184,112,22);limitTitle.setColour(juce::Label::textColourId,gill::twin::ink);limit.setBounds(375,184,138,24);connect.setBounds(276,222,228,29);list.setBounds(22,298,736,128);for(int i=0;i<3;++i){offsetLabels[size_t(i)].setBounds(22+i*247,438,60,23);offsets[size_t(i)].setBounds(83+i*247,438,181,23);}status.setBounds(22,477,736,28);inMeter.setBounds(29,462,110,18);outMeter.setBounds(643,462,110,18);}else{name.setBounds(230,362,320,28);role.setBounds(330,94,120,28);gain.setSliderStyle(juce::Slider::LinearVertical);gain.setTextBoxStyle(juce::Slider::TextBoxBelow,false,86,24);gain.setBounds(340,158,100,144);lock.setBounds(350,313,95,25);status.setBounds(160,338,460,20);identity.setBounds(214,407,158,26);disconnect.setBounds(402,407,164,26);inMeter.setBounds(34,366,145,22);outMeter.setBounds(608,366,145,22);}}

int GillMixEditor::getNumRows(){return static_cast<int>(processor.tracks.size());}
void GillMixEditor::paintListBoxItem(int row,juce::Graphics&g,int width,int height,bool selected){if(row<0||row>=getNumRows())return;const auto&t=processor.tracks[static_cast<size_t>(row)];g.fillAll(juce::Colour(selected?0xff4b3d69:row%2?0xff22212b:0xff19181f));g.setColour(juce::Colour(t.row.reachable?0xffd4e9f9:0xff7d99af));g.drawRoundedRectangle(8,11,14,14,3,1);if(t.selected){g.fillRoundedRectangle(11,14,8,8,2);}g.setFont(juce::FontOptions(13));g.drawText(juce::String::fromUTF8(t.row.local.name),33,1,210,height-2,juce::Justification::centredLeft);g.setFont(juce::FontOptions(12));const auto role=juce::String(roleName(t.role))+(t.confirmed?(t.confidence<.99f?" / HIGH":""):" / CHECK");g.drawText(t.row.duplicate?"DUPLICATE ID":role,252,1,120,height-2,juce::Justification::centredLeft);g.drawText(juce::String(GainValue::decode(t.row.local.gain),1)+" dB",391,1,93,height-2,juce::Justification::centredLeft);g.drawText(t.hasProposal?juce::String(t.proposedDb,1)+" dB":t.locked?"LOCKED":t.row.owner==processor.bus.runtimeId()?"CONNECTED":"AVAILABLE",493,1,width-500,height-2,juce::Justification::centredLeft);}
void GillMixEditor::listBoxItemClicked(int row,const juce::MouseEvent&e){if(row<0||row>=getNumRows())return;const auto&t=processor.tracks[static_cast<size_t>(row)];if(e.x<28){processor.chooseTrack(t.row.local.persistent,!t.selected);processor.service();list.repaint();}else editTrack(row);}
void GillMixEditor::editTrack(int row){const auto t=processor.tracks[static_cast<size_t>(row)];juce::PopupMenu menu;for(int i=0;i<=4;++i)menu.addItem(10+i,roleName(static_cast<Role>(i)),true,t.role==static_cast<Role>(i));menu.addSeparator();menu.addItem(30,t.locked?"UNLOCK PROPOSAL":"LOCK PROPOSAL");menu.addItem(40,"LEVEL -1 dB",t.row.owner==processor.bus.runtimeId());menu.addItem(41,"LEVEL +1 dB",t.row.owner==processor.bus.runtimeId());menu.addItem(42,"DISCONNECT",t.row.owner==processor.bus.runtimeId());juce::Component::SafePointer<GillMixEditor>safe(this);menu.showMenuAsync(juce::PopupMenu::Options(),[safe,t](int result){if(!safe)return;if(result>=10&&result<=14)safe->processor.chooseRole(t.row.local.persistent,static_cast<Role>(result-10));if(result==30)safe->processor.lockTrack(t.row.local.persistent,!t.locked);if(result==40||result==41)safe->processor.manualGain(t.row.address.runtime,std::clamp(GainValue::decode(t.row.local.gain)+(result==40?-1.f:1.f),-24.f,6.f));if(result==42)safe->processor.bus.disconnect(t.row.address.runtime);safe->processor.service();safe->list.repaint();});}
void GillMixEditor::timerCallback(){updating=true;if(!name.hasKeyboardFocus(true))name.setText(juce::String::fromUTF8(processor.localSnapshot().name),false);if(processor.kind==GillMixKind::master)preset.setSelectedId(processor.getCurrentProgram()+1,juce::dontSendNotification);status.setText(processor.status,juce::dontSendNotification);const auto db=[](float x){return juce::String(x>1e-6f?20*std::log10(x):-120.f,1);};inMeter.setText("IN "+db(processor.meterIn()),juce::dontSendNotification);outMeter.setText("OUT "+db(processor.meterOut()),juce::dontSendNotification);if(processor.kind==GillMixKind::master){list.updateContent();list.repaint();apply.setEnabled(processor.canApply());undo.setEnabled(processor.canUndo());learn.setButtonText(processor.isLearning()?"STOP "+juce::String(processor.learnedSeconds(),0)+"s":"LEARN");}else{const auto s=processor.localSnapshot();role.setSelectedId(static_cast<int>(s.role)+1,juce::dontSendNotification);lock.setToggleState(s.locked,juce::dontSendNotification);}updating=false;repaint();}

